// Postbuild: hapus KV binding dari wrangler.json generated by @astrojs/cloudflare
// Mencegah error "namespace already exists" di Cloudflare Pages deploy
const fs = require('fs');
const path = require('path');

const wranglerPath = path.join(process.cwd(), 'dist', 'client', 'wrangler.json');
if (!fs.existsSync(wranglerPath)) {
  console.log('[clean-wrangler] wrangler.json not found at', wranglerPath);
  process.exit(0);
}

const config = JSON.parse(fs.readFileSync(wranglerPath, 'utf-8'));
let changed = false;

if (config.kv_namespaces && config.kv_namespaces.length > 0) {
  config.kv_namespaces = [];
  changed = true;
}
if (config.previews?.kv_namespaces && config.previews.kv_namespaces.length > 0) {
  config.previews.kv_namespaces = [];
  changed = true;
}

if (changed) {
  fs.writeFileSync(wranglerPath, JSON.stringify(config, null, 2) + '\n');
  console.log('[clean-wrangler] Removed SESSION KV binding from wrangler.json');
} else {
  console.log('[clean-wrangler] No KV binding found, no changes');
}
